import Legend = require( './index' );


// TESTS //

// The function returns a legend instance...
{
	new Legend( { 'fill': 'colorScale' } ); // $ExpectType Legend
	new Legend( { 'fill': 'colorScale', 'orient': 'left' } ); // $ExpectType Legend
	new Legend( { 'fill': 'colorScale', 'orient': 'left', 'title': 'Legend Title', 'direction': 'horizontal' } ); // $ExpectType Legend

	Legend( { 'fill': 'colorScale' } ); // $ExpectType Legend
	Legend( { 'fill': 'colorScale', 'orient': 'left' } ); // $ExpectType Legend
	Legend( { 'fill': 'colorScale', 'orient': 'left', 'title': 'Legend Title', 'direction': 'horizontal' } ); // $ExpectType Legend
}

// The compiler throws an error if the function is not provided an options argument...
{
	new Legend(); // $ExpectError
	Legend(); // $ExpectError
}

// The compiler throws an error if the function is provided an options argument which is not an object...
{
	new Legend( '5' ); // $ExpectError
	new Legend( 5 ); // $ExpectError
	new Legend( true ); // $ExpectError
	new Legend( false ); // $ExpectError
	new Legend( null ); // $ExpectError
	new Legend( [] ); // $ExpectError
	new Legend( ( x: number ): number => x ); // $ExpectError

	Legend( '5' ); // $ExpectError
	Legend( 5 ); // $ExpectError
	Legend( true ); // $ExpectError
	Legend( false ); // $ExpectError
	Legend( null ); // $ExpectError
	Legend( [] ); // $ExpectError
	Legend( ( x: number ): number => x ); // $ExpectError
}

